    /// Builtins whose body reads the host wall clock. The backend derives the
    /// `porf_host.wall_clock_millis` import (and therefore every later import
    /// index) from this, so a new clock reader must be listed here or its
    /// emitter has no import to call.
    pub const fn requires_wall_clock(self) -> bool {
        matches!(
            self,
            Self::DateNow
                | Self::TemporalNowInstant
                | Self::TemporalNowZonedDateTimeIso
                // `format()` with no argument formats the current instant.
                | Self::IntlDateTimeFormatBoundFormat
                | Self::IntlDateTimeFormatPrototypeFormatToParts
        )
    }

    pub const fn constructable(self) -> bool {
        matches!(
            self,
            Self::FunctionConstructor
                | Self::IteratorConstructor
                | Self::PromiseConstructor
                | Self::MapConstructor
                | Self::WeakMapConstructor
                | Self::WeakSetConstructor
                | Self::WeakRefConstructor
                | Self::FinalizationRegistryConstructor
                | Self::AsyncDisposableStackConstructor
                | Self::SetConstructor
                | Self::BoundFunctionInvoker
                | Self::ObjectConstructor
                | Self::ProxyConstructor
                | Self::ArrayConstructor
                | Self::ArrayBufferConstructor
                | Self::SharedArrayBufferConstructor
                | Self::DataViewConstructor
                | Self::DateConstructor
                | Self::TemporalInstantConstructor
                | Self::TemporalZonedDateTimeConstructor
                | Self::TemporalPlainDateConstructor
                | Self::TemporalPlainTimeConstructor
                | Self::TemporalPlainYearMonthConstructor
                | Self::TemporalPlainMonthDayConstructor
                | Self::TemporalPlainDateTimeConstructor
                | Self::TemporalDurationConstructor
                | Self::IntlLocaleConstructor
                | Self::IntlDateTimeFormatConstructor
                | Self::RegExpConstructor
                | Self::Float64ArrayConstructor
                | Self::Float32ArrayConstructor
                | Self::Int32ArrayConstructor
                | Self::Int16ArrayConstructor
                | Self::Int8ArrayConstructor
                | Self::Uint32ArrayConstructor
                | Self::Uint16ArrayConstructor
                | Self::Uint8ArrayConstructor
                | Self::Uint8ClampedArrayConstructor
                | Self::BigInt64ArrayConstructor
                | Self::BigUint64ArrayConstructor
                | Self::NumberConstructor
                | Self::StringConstructor
                | Self::BooleanConstructor
                | Self::BigIntConstructor
                | Self::SymbolConstructor
                | Self::ErrorConstructor
                | Self::EvalErrorConstructor
                | Self::AggregateErrorConstructor
                | Self::SuppressedErrorConstructor
                | Self::RangeErrorConstructor
                | Self::SyntaxErrorConstructor
                | Self::TypeErrorConstructor
                | Self::URIErrorConstructor
                | Self::ReferenceErrorConstructor
        )
    }

    pub const fn is_error_constructor(self) -> bool {
        matches!(
            self,
            Self::ErrorConstructor
                | Self::EvalErrorConstructor
                | Self::AggregateErrorConstructor
                | Self::SuppressedErrorConstructor
                | Self::RangeErrorConstructor
                | Self::SyntaxErrorConstructor
                | Self::TypeErrorConstructor
                | Self::URIErrorConstructor
                | Self::ReferenceErrorConstructor
        )
    }

    pub const fn is_static_method(self) -> bool {
        matches!(
            self,
            Self::ObjectCreate
                | Self::ObjectAssign
                | Self::ObjectGetPrototypeOf
                | Self::ObjectSetPrototypeOf
                | Self::ObjectDefineProperty
                | Self::ObjectDefineProperties
                | Self::ObjectGetOwnPropertyDescriptor
                | Self::ObjectGetOwnPropertyDescriptors
                | Self::ObjectGetOwnPropertyNames
                | Self::ObjectGetOwnPropertySymbols
                | Self::ObjectKeys
                | Self::ObjectValues
                | Self::ObjectEntries
                | Self::ObjectHasOwn
                | Self::ObjectIs
                | Self::ProxyRevocable
                | Self::ReflectConstruct
                | Self::ReflectApply
                | Self::ReflectGet
                | Self::ReflectGetPrototypeOf
                | Self::ReflectSet
                | Self::ReflectHas
                | Self::ReflectDefineProperty
                | Self::ReflectDeleteProperty
                | Self::ReflectIsExtensible
                | Self::ReflectPreventExtensions
                | Self::ReflectSetPrototypeOf
                | Self::ReflectOwnKeys
                | Self::IteratorFrom
                | Self::IteratorConcat
                | Self::IteratorZip
                | Self::IteratorZipKeyed
                | Self::ArrayFrom
                | Self::ArrayFromAsync
                | Self::ArrayOf
                | Self::ArrayIsArray
                | Self::ArrayBufferIsView
                | Self::DateNow
                | Self::DateParse
                | Self::DateUtc
                | Self::BigIntAsIntN
                | Self::BigIntAsUintN
                | Self::NumberIsInteger
                | Self::NumberIsSafeInteger
                | Self::NumberIsFinite
                | Self::NumberIsNaN
                | Self::SymbolFor
                | Self::SymbolKeyFor
                | Self::MathAbs
                | Self::MathAcos
                | Self::MathAcosh
                | Self::MathAsin
                | Self::MathAsinh
                | Self::MathAtan
                | Self::MathAtan2
                | Self::MathAtanh
                | Self::MathCbrt
                | Self::MathCeil
                | Self::MathClz32
                | Self::MathCos
                | Self::MathCosh
                | Self::MathExp
                | Self::MathExpm1
                | Self::MathF16Round
                | Self::MathFloor
                | Self::MathFround
                | Self::MathHypot
                | Self::MathImul
                | Self::MathLog
                | Self::MathLog10
                | Self::MathLog1p
                | Self::MathLog2
                | Self::MathPow
                | Self::MathRandom
                | Self::MathRound
                | Self::MathSign
                | Self::MathSin
                | Self::MathSinh
                | Self::MathSqrt
                | Self::MathSumPrecise
                | Self::MathTan
                | Self::MathTanh
                | Self::MathTrunc
                | Self::MathMin
                | Self::MathMax
                | Self::ErrorIsError
        )
    }

    pub const fn is_boxed_primitive_constructor(self) -> bool {
        matches!(
            self,
            Self::NumberConstructor | Self::StringConstructor | Self::BooleanConstructor
        )
    }

